contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint value) public payable {
        uint beforeBal = address(c).balance;
        uint beforeCount = c.depositsCount(); if (__ESBMC_reverted()) return;
        bool reverted;
        c.withdraw(value); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        uint afterBal = address(c).balance;
        uint afterCount = c.depositsCount(); if (__ESBMC_reverted()) return;

        assert(
            afterCount == beforeCount &&
            (reverted ? afterBal == beforeBal : afterBal + value == beforeBal)
        );
    }

    receive() external payable {}
}

